class Solution {
    public int[] firstMissing(int[] nums, int k) {
        int[] out = new int[k];
        int found = 0, x = 1;
        while (found < k) {
            boolean taken = false;
            for (int v : nums) if (v == x) { taken = true; break; }
            if (!taken) out[found++] = x;
            x++;
        }
        return out;
    }
}

