// A small hash set of ints: open addressing, linear probing.
typedef struct { int key; bool used; } Slot;

static unsigned slotOf(int key, unsigned mask) {
    unsigned long long h = (unsigned long long) (long long) key * 0x9E3779B97F4A7C15ULL;
    return (unsigned) (h >> 32) & mask;
}

int* firstMissing(int* nums, int numsSize, int k, int* returnSize) {
    unsigned cap = 1;
    while (cap < 2u * numsSize) cap <<= 1;
    Slot* have = calloc(cap, sizeof(Slot));
    for (int i = 0; i < numsSize; i++) {
        unsigned s = slotOf(nums[i], cap - 1);
        while (have[s].used && have[s].key != nums[i]) s = (s + 1) & (cap - 1);
        have[s] = (Slot) {nums[i], true};
    }
    int* out = malloc(k * sizeof(int));
    for (int found = 0, x = 1; found < k; x++) {
        unsigned s = slotOf(x, cap - 1);
        while (have[s].used && have[s].key != x) s = (s + 1) & (cap - 1);
        if (!have[s].used) out[found++] = x;
    }
    free(have);
    *returnSize = k;
    return out;
}

