class Solution:
    def firstMissing(self, nums: List[int], k: int) -> List[int]:
        limit = len(nums) + k
        present = [False] * (limit + 1)
        for v in nums:
            if 1 <= v <= limit:
                present[v] = True
        out = []
        x = 1
        while len(out) < k:
            if not present[x]:
                out.append(x)
            x += 1
        return out

