class Solution {
    public int[] firstMissing(int[] nums, int k) {
        int limit = nums.length + k;
        boolean[] present = new boolean[limit + 1];
        for (int v : nums) {
            if (v >= 1 && v <= limit) present[v] = true;
        }
        int[] out = new int[k];
        for (int found = 0, x = 1; found < k; x++) {
            if (!present[x]) out[found++] = x;
        }
        return out;
    }
}

